-- plan v5 as approved (merged/plan_v5.json): CPL form f2 / ad set a2, NIOS form f3 / ad set a3, built as 1310 / 8420 and 1320 / 8430
INSERT INTO public.ads_meta_strategy (title, status, goal, version, approved_version, build) VALUES ('V5 real', 'approved', '{}', 5, 5,
  '{"version": 5, "steps": {"form:f2": {"id": "1310"}, "form:f3": {"id": "1320"}, "adset:a2": {"id": "8420"}, "adset:a3": {"id": "8430"}}}');
INSERT INTO public.ads_meta_strategy_version (strategy_id, version, plan) SELECT id, 5, $plan${"title": "CPL counselling, all India: 1 lead ad set, 4 Reels (student, parent, NIOS route, CPL reality), call button, ₹100/day", "summary": "One Instant Form lead campaign with ONE all-India ad set at ₹100 a day (₹3,000 for 30 days), replacing the Delhi + 40 km test, where views cost ₹180 per 1,000 (₹331.26 for 1,842 views, 4 leads, ₹83 per lead). It runs up to 4 vertical Reels: v1, the proven student Reel (3 leads at ₹72), unchanged; v4, a parent-trust Reel; v5, the NIOS route for students who did class 12 without Physics and Maths; and v6, what a CPL really involves (DGCA medical, DGCA exams, 200 hours). The parent Reel v2 is retired because its '₹40 lakh' line contradicts the prospectus; until the owner settles the fee line, no ad states a fee amount and every ad says the full fee breakdown comes on WhatsApp, in writing. The higher-intent form keeps its 7 fields, but its thank-you button now starts a call to 93555 66991 instead of opening the website. ₹100 a day buys about 1-2 leads a day, so Meta will stay 'learning limited' all month: each ad is judged only after about ₹500 of its own spend, and nothing that resets learning is touched in the first 7 days. Likely result: about 50 leads at about ₹60 (range 36-75), of which about 15 CPL-qualified and a share on the NIOS route track; the 500 target is not reachable at this budget.", "goal": {"objective": "admissions", "monthly_target": 500, "kpi": "The KPI is cost per qualified lead. A lead is qualified when a counsellor confirms all three: (1) Physics and Maths in class 12, meaning passed, a graduate who had them, or currently studying them in class 12; (2) an adult student or a parent or guardian is on the call, and a parent or guardian always takes part when the student is under 18; (3) they want to start within 3 months, or right after the 2027 board results if the student is in class 12 now. It is tracked weekly next to cost per Meta lead, the split of funding answers and admissions. Leads who answer 'Passed with other subjects' go to the NIOS route track: graded 'NIOS route', a valid lead for the NIOS offer, never counted or sent to Meta as CPL-qualified, and not closed as lost; they are reported weekly as cost per NIOS-route lead. The weekly line also shows cost per 1,000 views and the share of leads called within 5 minutes."}, "budget": {"monthly_total": 3000, "daily_total": 100, "phases": [{"name": "Test", "days": "1-7", "daily": 100, "focus": "Day 1 is the day a2 goes live (target 27 Nov, latest 30 Nov) once v4 and v5 are approved; the Delhi ad set is paused the same day, so only one ad set spends at a time and spend stays ₹100 a day. No edits that reset learning (budget, audience, form, new or edited creatives) except the rule-1 exceptions. Call every lead within 5 minutes from 10am to 7pm, night leads by 10:30am, and grade each the same day."}, {"name": "Judge", "days": "8-21", "daily": 100, "focus": "Day-8 low-volume check. Judge an ad only after it has spent about ₹500 (at ₹100 a day across up to 4 ads this takes 5-20 days, and Meta usually gives most spend to 1-2 ads). Until each ad has 5+ qualified leads, judge on cost per Meta lead, Physics & Maths share and funding split; judge v5 on cost per NIOS-route lead. Day 14 is the first day a state exclusion can be proposed. Brief a replacement Reel by day 21."}, {"name": "Refresh", "days": "22-30", "daily": 100, "focus": "Replace the weakest or most tired ad (week-5 fatigue) with one new Reel, ideally the owner's real footage (students, aircraft, Dwarka office). Month report; the owner decides the next month's budget."}]}, "campaigns": [{"key": "c1", "name": "WOA | Leads | CPL counselling | India | Reels | Nov26", "objective": "OUTCOME_LEADS", "budget_level": "adset", "daily_budget": null, "reason": "Lead generation with an Instant Form is the account's proven objective (₹41 per lead over 655 leads); conversations cost ₹1,979 per lead and the WhatsApp button ₹927 (CONTEXT.patterns). Key c1 is the campaign already created in Meta (120250492141030016), so the new ad set sits in it; rename it to 'India' in Ads Manager. Two ad sets: CPL (a2, ₹70) and NIOS route (a3, ₹30), owner's split of the fixed ₹100/day.", "adsets": [{"key": "a2", "name": "India | Advantage+ audience 18-65 | Advantage+ placements | f2", "daily_budget": 70, "optimization": "LEAD_GENERATION", "audience": {"funnel": "prospecting", "locations": [{"name": "India", "type": "country"}], "age_min": 18, "age_max": 65, "genders": "all", "interests": ["Aviation", "Pilot (aviation)", "Flight training"], "advantage_audience": true, "include_audiences": [], "exclude_audiences": ["crm_customers", "crm_leads_30"]}, "placements": "advantage", "form": "f2", "ads": ["v1", "v4", "v6"], "reason": "Owner, 23 Nov: total stays ₹100/day, split CPL ₹70 / NIOS ₹30 (adjustable from the Budget split card on Overview). ONE ad set for all of India (owner, 23 Nov; lesson 1). New key a2 because a1 is the live Delhi + 40 km ad set (120250492241490016), which is paused the day a2 goes live; v1's Instagram post is reused, so its likes and comments carry over.\n\nLocation: India. The Delhi radius made views cost ₹168-206 per 1,000 (CONTEXT.last_test). North-India region and city lead ads cost about ₹78 per 1,000 in Feb 2026 (regional, not country-wide, history), so cheaper reach is expected but not proven for country-wide lead ads; the 'IN, no leads' pattern came from conversations ad sets (lesson 11). No state is excluded at start (CONTEXT.locations: 'too few leads' everywhere).\n\nAudience: Advantage+ audience, not a manual 18-45. Parents decide and fund the training and many are over 45; a manual 18-45 cap is a hard limit that would cut them out, while under Advantage+ audience Meta keeps 18-65 as the limits and treats interests only as hints. 2 of the 4 test leads were parents (both from v1), and the account's ₹39-per-lead ad set ran 18-65 with Advantage on. Under-18s are never targeted. Hard exclusions: admissions (crm_customers) and last-30-day leads (crm_leads_30), both ready in Meta. Lookalikes lal_qualified_1 / lal_hot_1 are left out: their seeds have only a handful of people, so as hints they add nothing yet.\n\nPlacements: Advantage+ (Instagram Reels gave 117 of 191 breakdown leads; no placement lost meaningful money). All creatives are 1080x1920 vertical video.\n\nAds: at most 4. ₹100 a day across 4 ads is about ₹25 each if spread evenly, so an ad needs about 20 days to reach the ₹500 judging point; a 5th ad would mean no ad can be judged within the month. Four covers four different people and angles (student, parent, NIOS route, graduate/realistic path), which Advantage+ needs to find different buyers.\n\nLearning: about 7-14 leads a week against Meta's roughly 50 a week (PPC Land, third-party), so the ad set stays learning limited; that is expected at this budget and is why the structure stays this simple."}, {"key": "a3", "name": "India | NIOS route | Advantage+ audience 18-65 | Advantage+ placements | f3", "daily_budget": 30, "optimization": "LEAD_GENERATION", "audience": {"funnel": "prospecting", "locations": [{"name": "India", "type": "country"}], "age_min": 18, "age_max": 65, "genders": "all", "interests": ["Pilot (aviation)", "Aviation"], "advantage_audience": true, "include_audiences": [], "exclude_audiences": ["crm_customers", "crm_leads_30"]}, "placements": "advantage", "form": "f3", "ads": ["v5"], "reason": "Owner, 23 Nov: a separate NIOS ad and track with its own budget so it is guaranteed spend (₹30 of the ₹100/day; the owner moves the split on the Budget split card). Own form f3 so these leads go straight to the CRM's NIOS route track and are never counted or reported to Meta as CPL-qualified. Same all-India Advantage+ audience and placements as a2; one ad only, so the small budget is not split further."}]}], "forms": [{"key": "f2", "name": "WOA CPL Counselling - Higher Intent - Nov26 v5 (call button)", "type": "higher_intent", "headline": "CPL counselling call + fees in writing", "intro": "4 quick questions. A We One Aviation counsellor from Dwarka calls you the same day (10am-7pm; later forms next morning) about your eligibility and the full CPL roadmap (medical, DGCA exams, 200 hours flying), then sends current fees on WhatsApp, in writing. No commitment. CPL needs Physics and Maths in class 12; if they were not taken, the counsellor explains the NIOS route.", "questions": [{"type": "FULL_NAME"}, {"type": "PHONE"}, {"type": "CITY"}, {"type": "CUSTOM", "label": "Who is filling this form?", "options": ["Student (18+)", "Parent / guardian"]}, {"type": "CUSTOM", "label": "Class 12 status?", "options": ["Passed with Physics & Maths", "Passed with other subjects", "Currently in class 12", "Graduate"]}, {"type": "CUSTOM", "label": "When do you want to start?", "options": ["Within 1 month", "In 1-3 months", "In 3-6 months", "Just exploring"]}, {"type": "CUSTOM", "label": "How do you plan to fund the training?", "options": ["Family funded", "Education loan", "Family + education loan", "Still working it out"]}], "thank_you": {"title": "Thank you! Talk to a counsellor now", "body": "Tap Call now to reach our counsellor on 93555 66991 (10am-7pm). After 7pm we call you by 10:30am next morning. Fees come on WhatsApp, in writing. If the student is under 18 we speak with a parent.", "button_text": "Call now", "button_type": "CALL_BUSINESS", "phone": "+919355566991"}}, {"key": "f3", "name": "WOA NIOS route - Higher Intent - Nov26 (call button)", "type": "higher_intent", "headline": "NIOS route: your Physics-Maths + CPL plan", "intro": "4 quick questions. A We One Aviation counsellor calls you (10am-7pm; later forms next morning) and explains the NIOS route for Physics and Maths, then the CPL roadmap after it (DGCA medical, DGCA exams, 200 hours flying). Fees come on WhatsApp, in writing. Free career counselling, no commitment.", "questions": [{"type": "FULL_NAME"}, {"type": "PHONE"}, {"type": "CITY"}, {"type": "CUSTOM", "label": "Who is filling this form?", "options": ["Student (18+)", "Parent / guardian"]}, {"type": "CUSTOM", "label": "12th kis stream se?", "options": ["Arts", "Commerce", "Science without Maths", "Abhi 12th mein"]}, {"type": "CUSTOM", "label": "NIOS Physics-Maths ka status?", "options": ["Already enrolled", "Exam dena hai", "Guidance chahiye"]}, {"type": "CUSTOM", "label": "How do you plan to fund the training?", "options": ["Family funded", "Education loan", "Family + education loan", "Still working it out"]}], "thank_you": {"title": "Thank you! Your NIOS + CPL plan is next", "body": "Tap Call now to reach our counsellor on 93555 66991 (10am-7pm). After 7pm we call you by 10:30am next morning. Fees come on WhatsApp, in writing. If the student is under 18 we speak with a parent.", "button_text": "Call now", "button_type": "CALL_BUSINESS", "phone": "+919355566991"}}], "creatives": [{"key": "v1", "format": "video", "persona": "pcm_finisher", "cta": "SIGN_UP", "name": "Reel (IG post) | Persona: pcm_finisher (student 18+) | Pilot after 12th: check this before paying fees | Hinglish", "angle": "Persona: pcm_finisher (Class 12 PCM finisher, 18+). Check the order of the CPL steps before paying any fees, then get the fees on WhatsApp in writing.", "concept": "Know the order of CPL steps before you pay anyone.", "headline": "Pilot after 12th: check this before paying fees", "description": "Fees on WhatsApp, in writing. No commitment.", "primary_text": "12th ke baad pilot banna hai? Fees bharne se pehle ye order samjho 👇\n\n1️⃣ DGCA Class 2 medical, sabse pehle\n2️⃣ DGCA theory exams + RTR(A)\n3️⃣ Kam se kam 200 ghante flying\n(CPL ke liye Class 1 medical bhi zaroori hai)\n\nFree career counselling call: aapki eligibility check, poora CPL roadmap, aur current fees WhatsApp pe likhit mein. No commitment.\n\n📞 Call/WhatsApp: 93555 66991\n📍 We One Aviation, Dwarka, New Delhi\n\n#PilotAfter12th #CPL #DGCA #PilotTraining #WeOneAviation", "visual_brief": "UNCHANGED, already approved and live: Reel Studio's Instagram Reel https://www.instagram.com/reel/Df9ZltZinVD/ (build.posts.v1), 1080x1920, run with 'Use in ads'. In 'Use in ads' the post's own caption is the ad text, so primary_text above is now the live caption word for word (it passed the rule-3 check: phone 93555 66991, 'free' only in 'Free career counselling call', no fee amount, no banned wording). No re-edit. Video as posted: hook 'Pilot after 12th? Check this before paying fees', the steps in order, close with the owner-approved counselling line, logo and 'Dwarka, New Delhi'.", "why": "Top ad of the test, 20-23 Nov: ₹214.90 for 3 leads (₹72), 0.78% click rate, 1,278 views at ₹168 per 1,000 (CONTEXT.last_test). Still under the ₹500 judging point (lesson 4), so it is kept unchanged. 2 of its 3 leads were parents (lesson 9). Reels gave 117 of 191 breakdown leads; short text won (₹41 against ₹122 per lead)."}, {"key": "v4", "format": "video", "persona": "parent", "cta": "LEARN_MORE", "name": "Reel | Persona: parent | Parent trust: get these 3 things in writing before paying | Hinglish", "angle": "Persona: parent. Trust and process: before paying any academy, get three things in writing (what DGCA requires, who does what, the full fee breakdown) and visit the Dwarka classroom. No fee figure.", "concept": "A careful parent gets it in writing and visits before paying.", "headline": "Office dekhiye, fees likhit mein lijiye", "description": "Visit our Dwarka classroom or get a call", "primary_text": "Pilot training ka total kharcha lakhs mein hota hai, isliye faisla soch-samajh kar. Fees se pehle Dwarka office aakar dekhiye (ya phone pe baat kijiye), career counsellor se poora CPL roadmap samjhiye: DGCA medical, DGCA exams, 200 ghante flying. Fees ka breakup WhatsApp pe, likhit mein. Free career counselling, koi commitment nahi.", "visual_brief": "Source: Reel Studio presenter_studio Reel, posted on Instagram and run with 'Use in ads' (the post caption becomes the ad text). 9:16, 1080x1920, 25-32 s, captions burned in (must work with sound off). Keep text and faces out of the top 14 %, the bottom 35 % and 6 % each side. 0-3 s: presenter close-up + on-screen 'Pilot ka sapna? Fees baad mein'. Middle: Dwarka office + classroom, then the roadmap as a list card (DGCA medical -> DGCA exams -> 200 hrs flying), then a WhatsApp-style ui_card 'Fees: WhatsApp pe, likhit mein'. Close: presenter CTA, end card 'FREE CAREER COUNSELLING' / 'Eligibility + roadmap, no commitment', logo, 'Dwarka, New Delhi'. Stock/3D shots now; every [OWNER FOOTAGE] slot is swapped for the owner's phone clips when they arrive (see FOOTAGE_REQUEST.md: office, classroom, counsellor desk). The AI presenter is a presenter, never introduced as the counsellor or a staff member. Adults only on screen, no airline logos or liveries, no fee amounts, no phone number in the video.", "why": "Parents fund the training and weigh cost, genuineness and what is provided (CONTEXT.personas.parent). The parent Reel v2 had the higher click rate (1.06% against 0.78%) but its '₹40 lakh' line contradicts the prospectus (owner lesson 2), so v4 keeps the parent angle without any figure. Ground classes in Dwarka and online, and flying with partner flying schools, are on weoneaviation.in/dgca-ground-classes; eligibility, DGCA medical and 200 hours on the home page; the address on /contact. 'Lakhs mein' states the scale of the cost as a fact about the course (premium rule) without a figure, so it fits both the prospectus and the owner's figure.", "hook": "Jab bachcha kahe 'mujhe pilot banna hai', pehla kadam fees nahi.", "outline": ["Jab bachcha kahe, 'mujhe pilot banna hai'... pehla kadam fees nahi hai.", "Pehle institute ko khud parkhiye.", "Two thousand nine se Dwarka mein hain. Office aaiye, classroom dekhiye.", "Career counsellor poora roadmap samjhayenge: medical, DGCA exams, do sau ghante flying.", "Fees ka poora breakup WhatsApp pe, likhit mein. Likhit dekhe bina kuch mat bhariye.", "Delhi se bahar bhi, baat phone pe. Free career counselling, koi commitment nahi. Form bhariye."], "facts_to_verify": ["We One Aviation office: C-404, Ramphal Chowk, Dwarka, New Delhi (https://weoneaviation.in/faqs)", "Supporting aspiring pilots since 2009; online batches for students outside Delhi (https://weoneaviation.in/)", "200 hours of flying for a CPL; flight training with partner flying schools (https://weoneaviation.in/)"], "script": {"target_seconds": 30, "scenes": [{"scene": 1, "start": 0.0, "end": 4.0, "seconds": 4.0, "shot": "PRESENTER (hook, P1)", "spoken": "Jab bachcha kahe, 'mujhe pilot banna hai'... pehla kadam fees nahi hai.", "on_screen": "Pilot ka sapna? Fees baad mein", "visual": "Presenter close-up, slight push-in; behind_text 'FEES?' (amber).", "owner_footage": "[OWNER FOOTAGE: later optional - parent and student walking into the Dwarka office, backs to camera]"}, {"scene": 2, "start": 4.0, "end": 7.5, "seconds": 3.5, "shot": "B-ROLL", "spoken": "Pehle institute ko khud parkhiye.", "on_screen": "Pehle institute parkhiye", "visual": "Stock: parent reading documents at a table, close-up hands.", "owner_footage": "[OWNER FOOTAGE: office signboard + entrance, C-404 Ramphal Chowk, Dwarka]"}, {"scene": 3, "start": 7.5, "end": 12.5, "seconds": 5.0, "shot": "B-ROLL", "spoken": "Two thousand nine se Dwarka mein hain. Office aaiye, classroom dekhiye.", "on_screen": "2009 se Dwarka, New Delhi", "visual": "Stock classroom wide -> chip 'Dwarka, New Delhi'.", "owner_footage": "[OWNER FOOTAGE: classroom pan, whiteboard with a DGCA subject, empty or consenting adults]"}, {"scene": 4, "start": 12.5, "end": 18.5, "seconds": 6.0, "shot": "B-ROLL + GRAPHIC", "spoken": "Career counsellor poora roadmap samjhayenge: medical, DGCA exams, do sau ghante flying.", "on_screen": "Medical -> DGCA exams -> 200 hrs", "visual": "list_card with 3 rows revealed one per phrase over a desk shot.", "owner_footage": "[OWNER FOOTAGE: counsellor's hands drawing the roadmap on paper at the desk]"}, {"scene": 5, "start": 18.5, "end": 23.5, "seconds": 5.0, "shot": "B-ROLL + GRAPHIC", "spoken": "Fees ka poora breakup WhatsApp pe, likhit mein. Likhit dekhe bina kuch mat bhariye.", "on_screen": "Fees: WhatsApp pe, likhit mein", "visual": "ui_card (chat icon) 'Fees breakup - likhit mein' over phone-in-hand shot. No amounts visible.", "owner_footage": "[OWNER FOOTAGE: phone screen showing a WhatsApp chat with the amounts blurred/cropped out]"}, {"scene": 6, "start": 23.5, "end": 30.0, "seconds": 6.5, "shot": "PRESENTER (CTA, P2)", "spoken": "Delhi se bahar bhi, baat phone pe. Free career counselling, koi commitment nahi. Form bhariye.", "on_screen": "Free career counselling", "visual": "Presenter to camera, then end card FREE CAREER COUNSELLING.", "owner_footage": "[OWNER FOOTAGE: later replace with the real career counsellor saying the same line at the office desk (written consent)]"}], "total_seconds": 30.0, "spoken_words": 69}, "est_seconds": 30, "video_style": "presenter_studio", "caption": "Bachche ke pilot banne ka faisla? Fees se pehle institute parkhiye 👇\n\n✅ Dwarka office aaiye, classroom dekhiye (2009 se Dwarka mein)\n✅ Career counsellor se poora CPL roadmap: DGCA medical → DGCA exams → kam se kam 200 ghante flying (partner flying schools ke saath)\n✅ Fees ka poora breakup WhatsApp pe, likhit mein\n\nDelhi se bahar? Counselling phone pe, ground classes online batches mein.\nFree career counselling, koi commitment nahi.\n\n📞 Call/WhatsApp: 93555 66991\n📍 We One Aviation, C-404, Ramphal Chowk, Dwarka, New Delhi\n\n#PilotTraining #CPL #DGCA #ParentsGuide #WeOneAviation\n\nℹ️ Is video mein AI presenter hai.", "alt_hooks": ["Pilot training ki fees se pehle, ye 3 cheezein dekhiye.", "Fees bharne se pehle, institute ka office khud dekhiye.", "Pilot banne ka sapna bachche ka, faisla aapka: pehle roadmap."]}, {"key": "v5", "format": "video", "persona": "non_pcm", "cta": "SIGN_UP", "name": "Reel | Persona: non_pcm | NIOS route: pilot after 12th without Physics/Maths | Hinglish", "angle": "Persona: non_pcm. Eligibility first: DGCA needs Physics and Maths at 10+2, and Commerce or Arts students can add them through NIOS before starting CPL training.", "concept": "Two subjects stand between Commerce/Arts students and the CPL path: the NIOS route.", "headline": "Non-PCM? Pilot ka NIOS route", "description": "NIOS + CPL roadmap on a counselling call", "primary_text": "Arts/Commerce se 12th? Pilot ka raasta band nahi. DGCA ko 12th level pe Physics + Maths chahiye, aur ye dono NIOS se de sakte hain. ✔ Free counselling call ✔ Aapka NIOS + CPL plan ✔ Fees WhatsApp pe, likhit mein. Form bhariye, koi commitment nahi.", "visual_brief": "Source: Reel Studio presenter_studio Reel, posted on Instagram and run with 'Use in ads'. 9:16, 1080x1920, 25-30 s, captions burned in (sound-off readable). Safe zones: nothing key in the top 14 %, bottom 35 %, 6 % each side. 0-3 s: presenter + on-screen 'Physics-Maths nahi? Raasta hai'. Middle: ui_card 'DGCA: 10+2 Physics + Maths'; compare card '12th (other subjects)' -> 'NIOS: Physics + Maths'; text card 'Source: Air India cadet eligibility page' (text only, no Air India logo, livery or aircraft); flow chip row 'NIOS -> Medical -> DGCA exams -> Flying'. Close: presenter CTA + end card FREE CAREER COUNSELLING. Never say how long NIOS takes or promise a result; never imply a tie-up with Air India. Adults only on screen.", "why": "2 of the 4 test leads answered 'Passed with other subjects' (CONTEXT.last_test; lesson 6), and the owner decided a separate NIOS route ad and CRM track (23 Nov). The route is published: Air India's cadet eligibility page accepts Physics and Maths taken at 10+2 level through NIOS (cadetpilot.airindia.com/in/en/eligibility-criteria.html); the 10+2 Physics and Maths rule is on the weoneaviation.in home page. It gives these people a clear next step instead of losing them, and its leads are tracked as NIOS-route leads, not CPL-qualified.", "hook": "Arts ya Commerce se 12th? Pilot ka raasta band nahi hua.", "outline": ["Twelfth mein Physics-Maths nahi? Pilot ka raasta abhi bhi khula hai.", "DGCA CPL ke liye, twelfth mein Physics aur Maths zaroori hain.", "Hal hai NIOS. Sirf Physics aur Maths ka exam, NIOS se.", "Air India ki cadet eligibility mein bhi, yahi NIOS option likha hai.", "Phir wahi raasta: medical, DGCA exams, flying.", "Apna plan free career counselling mein banaiye. Form bhariye, koi commitment nahi."], "facts_to_verify": ["DGCA: applicants except PPL must have passed 10+2 with Physics and Mathematics (https://pariksha.dgca.gov.in/Form/PLT_FAQs, FAQ 7)", "Air India cadet eligibility: without Maths and Physics in 10+2, candidates may take these subjects at 10+2 level from NIOS (https://cadetpilot.airindia.com/in/en/eligibility-criteria.html)", "Removing the Physics/Maths rule is only a DGCA proposal, not notified (https://www.business-standard.com/india-news/dgca-pilot-training-arts-commerce-students-eligibility-125052700977_1.html)"], "script": {"target_seconds": 25, "style": "direct-response", "scenes": [{"scene": 1, "start": 0, "end": 2, "spoken": "Arts ya Commerce se 12th? Pilot ka raasta band nahi hua.", "on_screen": "ARTS / COMMERCE → PILOT? ✅", "visual": "Presenter close-up; huge text pops with a check"}, {"scene": 2, "start": 2, "end": 6, "spoken": "Sab kehte hain, PCM nahi toh pilot nahi. Ye aadha sach hai.", "on_screen": "❌ MYTH: PCM nahi = pilot nahi  |  ✅ FACT", "visual": "Split card myth vs fact"}, {"scene": 3, "start": 6, "end": 10, "spoken": "DGCA ko 12th level pe sirf do subjects chahiye: Physics aur Maths.", "on_screen": "Sirf 2 subjects: Physics ✔ Maths ✔", "visual": "Counter card"}, {"scene": 4, "start": 10, "end": 14, "spoken": "Ye dono aap NIOS se de sakte ho. Ministry of Education ka open board.", "on_screen": "NIOS = Govt. open board", "visual": "Presenter + label card"}, {"scene": 5, "start": 14, "end": 18, "spoken": "Uske baad wahi raasta: DGCA medical, ground exams, 200 ghante flying.", "on_screen": "NIOS → Medical → Exams → 200 hrs", "visual": "Progress bar fills step by step"}, {"scene": 6, "start": 18, "end": 22, "spoken": "Free counselling call mein aapka NIOS plus CPL plan, step by step.", "on_screen": "✔ Free call ✔ NIOS + CPL plan ✔ Fees likhit mein", "visual": "Checklist ticks"}, {"scene": 7, "start": 22, "end": 25, "spoken": "Neeche form bhariye. Do minute. Koi commitment nahi.", "on_screen": "↓ Form bhariye: 2 min", "visual": "Arrow down; end card FREE CAREER COUNSELLING"}]}, "est_seconds": 25, "video_style": "presenter_studio", "caption": "Physics-Maths ke bina 12th? Pilot ka raasta NIOS se khulta hai 👇\n\n📌 DGCA CPL ke liye 10+2 mein Physics aur Maths chahiye\n📌 NIOS se sirf ye do subjects clear kiye ja sakte hain (Air India ki cadet eligibility page pe bhi yahi option likha hai)\n📌 Uske baad wahi CPL raasta: DGCA medical → DGCA exams + RTR(A) → kam se kam 200 ghante flying\n\nFree career counselling: aapka step-by-step plan, aur fees WhatsApp pe likhit mein. Koi commitment nahi.\n\n📞 Call/WhatsApp: 93555 66991\n📍 We One Aviation, Dwarka, New Delhi (online batches bhi)\n\n#PilotAfter12th #NIOS #CPL #DGCA #WeOneAviation\n\nℹ️ Is video mein AI presenter hai.", "alt_hooks": ["PCM nahi tha? Pilot banne ke beech sirf 2 subjects hain.", "12th Commerce se, sapna cockpit ka?"]}, {"key": "v6", "format": "video", "persona": "pcm_finisher", "cta": "SIGN_UP", "name": "Reel | Persona: career_switcher (graduate 18+) | What a CPL really involves: medical, DGCA exams, 200 hours | Hinglish", "angle": "Persona: career_switcher. Realistic path, no shortcuts: what a CPL takes in steps, time and commitment, so only serious people fill the form; graduates can still start.", "concept": "CPL is more than flying: the real steps, time and cost, told straight.", "headline": "CPL ke 4 stages, seedhi baat", "description": "Your timeline on a counselling call", "primary_text": "CPL ke 4 stages: DGCA medical, DGCA ke 5 papers + RTR(A), kam se kam 200 ghante flying, phir eGCA pe licence application. Time aur kharcha har student ka alag; airline selection alag step hai. Free career counselling mein apna roadmap. Koi commitment nahi.", "visual_brief": "Source: Reel Studio presenter_studio Reel, posted on Instagram and run with 'Use in ads'. 9:16, 1080x1920, 30-34 s, captions burned in (sound-off readable). Safe zones: top 14 %, bottom 35 %, sides 6 % kept clear. 0-3 s: presenter + 'CPL = 4 stages'. A counter/number badge 1-2-3-4 carries the middle (one stage per 4-5 s): medical, 5 papers + RTR(A) with a '70 % har paper' chip, 200 hrs flying (stock training aircraft, no airline livery), eGCA licence application. Then an honest card: 'Time + kharcha: har student alag' / 'Job: alag selection'. Close: presenter CTA + end card FREE CAREER COUNSELLING. No salary, no job or pass promise, no fee amounts.", "why": "The account's form already gets 'Graduate' answers, and CONTEXT.personas.career_switcher asks about eligibility, CPL and fees. A plain account of the steps (DGCA medical, DGCA exams, RTR(A), 200 hours, 12-18 months: weoneaviation.in home page and /dgca-ground-classes) filters out people who expect a shortcut, which supports lead quality at ₹100 a day. Optional: it goes live only if approved by go-live day (rule 2); otherwise it is the first refresh Reel.", "hook": "CPL sirf flying nahi hai. Chaar stages hain.", "outline": ["CPL sirf flying nahi hai. Chaar stages hain.", "Ek: DGCA medical. Class 2 se shuru, CPL ke liye Class 1.", "Do: DGCA ke paanch written papers aur RTR. Har paper mein seventy percent.", "Teen: kam se kam do sau ghante flying.", "Chaar: sab clear, phir eGCA pe licence application.", "Time aur kharcha har student ka alag. Job ke liye airline selection alag hota hai.", "Apna roadmap free career counselling mein banaiye. Fees WhatsApp pe, likhit mein."], "facts_to_verify": ["Medical: Class 2 to begin, Class 1 for a CPL (https://weoneaviation.in/faqs)", "Pass mark 70 % in each written paper (CAR Section 7 Series B Part I para 5.6, https://www.dgca.gov.in/digigov-portal/?dynamicPage=civilAviationRequirements%2F6%2F0%2FviewDynamicRulesReq)", "CPL papers: Air Navigation, Meteorology, Air Regulations, Technical General, Technical Specific; RTR(A) separate (https://weoneaviation.in/blogs/dgca-exam-guide)", "200 hours of flying is mandatory for a CPL (https://weoneaviation.in/)"], "script": {"target_seconds": 33, "scenes": [{"scene": 1, "start": 0.0, "end": 3.5, "seconds": 3.5, "shot": "PRESENTER (hook, P1)", "spoken": "CPL sirf flying nahi hai. Chaar stages hain.", "on_screen": "CPL = 4 stages", "visual": "Presenter close-up; behind_text '4' (amber).", "owner_footage": null}, {"scene": 2, "start": 3.5, "end": 8.0, "seconds": 4.5, "shot": "B-ROLL + GRAPHIC", "spoken": "Ek: DGCA medical. Class 2 se shuru, CPL ke liye Class 1.", "on_screen": "1. DGCA medical", "visual": "Stock: clinic corridor (no patient faces), chip 'Class 2 -> Class 1'.", "owner_footage": null}, {"scene": 3, "start": 8.0, "end": 13.5, "seconds": 5.5, "shot": "B-ROLL + GRAPHIC", "spoken": "Do: DGCA ke paanch written papers aur RTR. Har paper mein seventy percent.", "on_screen": "2. 5 papers + RTR(A)", "visual": "list_card of the 5 subjects (short names), chip '70 % har paper'.", "owner_footage": "[OWNER FOOTAGE: DGCA ground class in Dwarka - teacher's hand on whiteboard, no faces needed]"}, {"scene": 4, "start": 13.5, "end": 18.0, "seconds": 4.5, "shot": "B-ROLL + GRAPHIC", "spoken": "Teen: kam se kam do sau ghante flying.", "on_screen": "3. 200 hrs flying", "visual": "Stock: small trainer aircraft take-off (no airline livery); counter 0 -> 200 HRS.", "owner_footage": "[OWNER FOOTAGE: partner flying school aircraft/cockpit clip, only if the owner has rights to it]"}, {"scene": 5, "start": 18.0, "end": 22.0, "seconds": 4.0, "shot": "B-ROLL + GRAPHIC", "spoken": "Chaar: sab clear, phir eGCA pe licence application.", "on_screen": "4. eGCA licence application", "visual": "Stock: hands typing on a laptop; ui_card 'Licence application: eGCA'.", "owner_footage": null}, {"scene": 6, "start": 22.0, "end": 27.0, "seconds": 5.0, "shot": "B-ROLL + GRAPHIC", "spoken": "Time aur kharcha har student ka alag. Job ke liye airline selection alag hota hai.", "on_screen": "Job: alag selection step", "visual": "compare card: 'CPL licence' vs 'Airline selection (alag step)'.", "owner_footage": "[OWNER FOOTAGE: students studying in the classroom, wide, consenting adults]"}, {"scene": 7, "start": 27.0, "end": 33.0, "seconds": 6.0, "shot": "PRESENTER (CTA, P2)", "spoken": "Apna roadmap free career counselling mein banaiye. Fees WhatsApp pe, likhit mein.", "on_screen": "Free career counselling", "visual": "Presenter to camera, end card FREE CAREER COUNSELLING.", "owner_footage": "[OWNER FOOTAGE: later replace with the real career counsellor at the desk (written consent)]"}], "total_seconds": 33.0, "spoken_words": 76}, "est_seconds": 33, "video_style": "presenter_studio", "caption": "CPL sirf flying nahi, 4 stages hain 👇\n\n1️⃣ DGCA medical: Class 2 se shuru, CPL ke liye Class 1\n2️⃣ DGCA ke 5 written papers + RTR(A), har paper mein 70% pass mark\n3️⃣ Kam se kam 200 ghante flying (partner flying schools ke saath)\n4️⃣ Sab clear hone ke baad eGCA pe licence application\n\nSeedhi baat: time aur kharcha har student ka alag hota hai, aur licence ke baad airline selection ek alag step hai.\n\nFree career counselling: aapka roadmap aur fees WhatsApp pe likhit mein. Koi commitment nahi.\n\n📞 Call/WhatsApp: 93555 66991\n📍 We One Aviation, Dwarka, New Delhi (online batches bhi)\n\n#CPL #DGCA #PilotTraining #PilotAfter12th #WeOneAviation\n\nℹ️ Is video mein AI presenter hai.", "alt_hooks": ["Pilot banne mein sirf flying nahi, chaar stages hain.", "200 ghante flying se pehle, do stages aur hain.", "CPL ka poora sach, chaar stages mein, bina filter."]}], "forecast": {"horizon_days": 30, "assumptions": [{"name": "Budget", "value": "₹100 a day × 30 days = ₹3,000", "source": "owner", "note": "Owner decision, 23 Nov: ₹100/day, one all-India ad set. The 30 days start on a2's go-live day. Only one ad set spends at a time (the Delhi ad set pauses that day), so no 30-day window goes above ₹3,000; the ₹331 already spent 20-23 Nov and the Delhi days until go-live belong to the v3 test. Account spending limit: on go-live day the owner sets it to amount spent so far + ₹3,000 and raises it by ₹3,000 every 30 days (Meta's limit is cumulative)."}, {"name": "Test result (Delhi + 40 km, 20-23 Nov)", "value": "₹331.26, 1,842 views, 4 leads: ₹83 per lead, ₹180 per 1,000 views, 2.17 leads per 1,000 views", "source": "history", "note": "CONTEXT.last_test: v1 ₹214.90, 1,278 views, 3 leads; v2 ₹116.36, 564 views, 1 lead. Small numbers: low confidence."}, {"name": "Cost of 1,000 views across India (estimate)", "value": "about ₹78 (range ₹75-115)", "source": "history", "note": "ESTIMATE from regional history, not country-wide lead ads: Feb 2026 north-India region/city lead campaign ₹8,474.55 ÷ 109,270 views = ₹78; lesson 3 gives ₹75 for Feb-Apr 2026; Nov 2023 campaign ₹115."}, {"name": "Leads per 1,000 views", "value": "1.67 to 2.17", "source": "history", "note": "Feb 2026: 183 leads ÷ 109,270 views = 1.67. Test: 4 ÷ 1,842 = 2.17. Viewers far from Dwarka may convert less, so the likely case uses the lower rate."}, {"name": "Low cost per lead", "value": "₹83", "source": "history", "note": "The test itself: ₹331.26 ÷ 4 = ₹82.8. Assumes cheaper all-India views are fully offset by lower intent."}, {"name": "Likely cost per lead", "value": "₹60", "source": "history", "note": "₹78 ÷ 1.67 leads per 1,000 views = ₹47 (Feb 2026); × 1.15 for the higher-intent form (Zapier, third-party) = ₹54; about +10% because the Feb ads used urgency copy that is now banned and Nov-Dec is off-season = ₹59, rounded to ₹60."}, {"name": "High cost per lead", "value": "₹40", "source": "history", "note": "The test's 2.17 leads per 1,000 views holds at ₹78 per 1,000: ₹36, rounded up to ₹40 (the test already used the higher-intent form, so no ×1.15)."}, {"name": "NIOS-route share of leads", "value": "30-50%", "source": "history", "note": "2 of 4 test leads (50%) answered 'Passed with other subjects' before any NIOS ad. v5 will add such leads; v4 and v6 state the Physics and Maths rule. Only 4 leads: low confidence. These leads count as leads (and in cost per lead) but never as CPL-qualified."}, {"name": "Lead to qualified (CPL)", "value": "20% / 30% / 40%", "source": "benchmark", "note": "Planning estimate carried from v3/v4; no published benchmark (research gaps). The CRM has 1 lead at 'interested' and 0 qualified, so it cannot give a rate yet. Replace with CRM grading after week 2."}, {"name": "Qualified to admission", "value": "15% / 20% / 25%", "source": "benchmark", "note": "Planning estimate carried from v3/v4; CRM shows 0 admissions from Meta leads."}, {"name": "Owner lead-to-admission rate (recorded, not applied)", "value": "50%", "source": "owner", "note": "CONTEXT.goal.lead_to_admission_pct. Applying it would mean 25 admissions from 50 leads, with no CRM evidence behind it."}, {"name": "Learning phase", "value": "stays 'learning limited'", "source": "benchmark", "note": "Meta needs about 50 optimisation events per ad set in 7 days (PPC Land, third-party, and Meta's learning-phase guidance); ₹100 a day gives about 7-14 leads a week."}, {"name": "What the 500 target needs", "value": "₹20,000-30,000 a month", "source": "history", "note": "500 × ₹40-60 per lead. The highest month on record gave 183 leads (Feb 2026)."}], "scenarios": {"low": {"spend": 3000, "leads": 36, "cpl": 83, "qualified": 7, "admissions": 1}, "likely": {"spend": 3000, "leads": 50, "cpl": 60, "qualified": 15, "admissions": 3}, "high": {"spend": 3000, "leads": 75, "cpl": 40, "qualified": 30, "admissions": 7}}, "math": "Spend: ₹100 × 30 = ₹3,000\nLow: ₹331.26 ÷ 4 = ₹82.8 → ₹83; ₹3,000 ÷ 83 = 36 leads (1.2 a day)\nLikely: ₹78 ÷ 1.67 = ₹46.7; × 1.15 = ₹53.7; × 1.10 = ₹59 → ₹60; ₹3,000 ÷ 60 = 50 leads (1.7 a day)\nHigh: ₹78 ÷ 2.17 = ₹35.9 → ₹40; ₹3,000 ÷ 40 = 75 leads (2.5 a day)\nNIOS-route leads (30-50%): low 11-18, likely 15-25, high 23-38; not counted as qualified\nCPL-qualified: 36 × 20% = 7; 50 × 30% = 15; 75 × 40% = 30\nAdmissions: 7 × 15% = 1; 15 × 20% = 3; 30 × 25% = 7\nLearning: 36-75 leads ÷ 4.3 weeks = 8-17 a week, under 50, so one ad set, learning limited\nJudging: ₹500 per ad ÷ ₹100 a day = 5 days if one ad gets all spend, about 20 days if 4 ads share evenly\nDay-8 check: ₹700 ÷ 8 leads = ₹87.5, worse than the ₹83 low case"}, "rules": [{"when": "Days 1-7 after a2 goes live", "then": "No edits to budget, audience, form or creatives (each resets learning). Only two exceptions: fixing a disapproval or policy problem; and adding, in one batch, any of v4, v5 or v6 that were approved after a2 launched under the rule-2 fallback."}, {"when": "Launch gate: v4 or v5 is not yet owner-approved and through the rule-3 check, or the builder cannot yet send the thank-you call button", "then": "Do not publish a2; the Delhi ad set keeps running with v1 only. If not ready by 30 Nov: publish a2 with v1 plus whatever is approved, pause the Delhi ad set, and add the rest in one batch on their approval day (rule-1 exception). If the builder patch is not ready by 30 Nov, build f2 with button_text 'Visit our website' (v3 behaviour) and say so. v6 joins only if approved by go-live day; otherwise it waits as the first refresh Reel."}, {"when": "Before any ad goes live (v1, v4, v5, v6): a caption or ad text does not match its primary_text, the phone is not 93555 66991, any ₹ or $ amount or fee figure appears in caption, voice-over or video, 'free' appears outside 'free career counselling' / 'free counselling call', a line asks the viewer about their education, health, age or money, or any banned, urgency, job, airline or pass wording appears", "then": "Reel Studio corrects it and the owner re-approves. Do not launch that ad until it matches."}, {"when": "Fee line: until the owner confirms in writing one CPL cost line and the prospectus, DM script and ads all say the same", "then": "No ad, caption, video, DM or thank-you screen states a fee amount; they may say the total runs into lakhs and that the full fee breakdown comes on WhatsApp, in writing. v2 stays retired. After the owner settles it, a fee-line variant can be proposed after day 14 as a replacement for the weakest ad (never a 5th ad)."}, {"when": "Day 7: a2's cost per 1,000 views is above ₹120 on 3 of the last 4 days", "then": "Check spend by state and report to the owner with the numbers. Make no location change before day 14."}, {"when": "Day 8 check: ₹700 or more spent and 8 leads or fewer (₹88+ per lead, worse than the ₹83 low case)", "then": "Check the form completion rate, ad comments and the first 3 seconds of each Reel. Ask Reel Studio for a new hook on the weaker one. Do not change the audience or budget that week."}, {"when": "From day 8: a creative has spent ₹500 or more with 0 leads while another creative has 3 or more leads", "then": "Pause it. Ask Reel Studio for a replacement for the same persona on the leading angle. An ad that Meta has given under ₹500 is not judged on results (lesson 4)."}, {"when": "Until each creative has 5 or more qualified leads in the CRM", "then": "Judge creatives on cost per Meta lead, the share of 'Passed with Physics & Maths' answers and the funding-answer split, not on cost per qualified lead. Judge v5 on cost per NIOS-route lead instead."}, {"when": "Day 14 or later (never earlier): one state has spent ₹300 or more with 0 leads and takes more than 25% of a2's spend", "then": "Propose to the owner to exclude that state (location is a hard limit). Make one change only, then wait 7 days. A state that looks weak on days 7-13 is only reported."}, {"when": "A lead arrives between 10am and 7pm and is not called within 5 minutes (CRM timestamp)", "then": "Alert the counsellor and the owner. Leads after 7pm get a WhatsApp acknowledgement from 93555 66991 the same evening and a call by 10:30am the next day."}, {"when": "A lead that arrived 10am-7pm has no CRM grade (Contacted / Qualified / NIOS route / Not qualified) by 7pm the same day; or a lead that arrived 7pm-10am has no grade by 12 noon on the next calling morning", "then": "Alert the owner. Make no creative or audience decision on quality until grading is complete."}, {"when": "A lead answers 'Passed with other subjects' (from day 1, including the 2 leads of 22 Nov)", "then": "On the first call the counsellor explains the published eligibility (10+2 with Physics and Maths) and the NIOS route (Physics and Maths taken at 10+2 level through NIOS), offers what the owner has confirmed for this track (guidance only until then), and grades the lead 'NIOS route'. No CPL admission promise before the NIOS results."}, {"when": "A creative's CTR is 20% or more below its week-1 CTR for 3 days in a row, or frequency is above 3, or week 5 arrives (history: CTR index 0.88 in week 5, 0.278 in week 6)", "then": "Launch a new version with new first 3 seconds, on the same angle and persona and through the rule-3 check, as a replacement (the ad set stays at 4 ads or fewer). Pause the tired one."}, {"when": "After 14 days: cost per lead is ₹60 or less, and 30% or more of called leads are graded Qualified", "then": "Tell the owner it is safe to raise the budget by about 20% at a time (₹100 → ₹120 a day), 3-4 days apart. Do this only if the owner approves going above ₹3,000."}, {"when": "A call shows the student is under 18, including 'Currently in class 12' answers", "then": "The counsellor speaks only with a parent or guardian, not with the minor alone. The lead is graded Qualified only once a parent or guardian takes part."}], "timeline": [{"when": "23-24 Nov", "what": "Owner pauses v2 in the Delhi ad set (fee line contradicts the prospectus; its caption asks about the child's subjects and medical), so the Delhi ad set runs v1 alone at ₹100 a day. Calls (CONTEXT.last_test, 23 Nov): 3 of the 4 test leads were called, 13.1-15.5 hours after arriving (the Indirapuram parent, the Delhi student and the Delhi parent, all from v1); the v2 student (New Delhi, Physics & Maths, family funded) has not been called and is called today. All 4 get a CRM grade today: 3 are still at lead_created and 1 (Delhi parent) at interested. The 2 'Passed with other subjects' leads get the NIOS-route call and tag. Owner gives counsellors the one-page education-loan note (documents, what the institute issues, lenders families have used; no approval promised). Owner decides: call button or WhatsApp button, which number has WhatsApp, what We One offers on the NIOS track, and whether 'total kharcha lakhs mein' is acceptable."}, {"when": "23-26 Nov", "what": "Creative agent writes v4, v5 and v6 scripts on these keys; Reel Studio renders them (1080x1920, presenter_studio); owner approves each; rule-3 check. Engineer deploys the builder patch (thank-you button type and phone; building a new version on the existing campaign)."}, {"when": "Go-live day (target 27 Nov, latest 30 Nov) = day 1", "what": "Create f2 and a2 in Meta (paused) with v1 + v4 + v5 (+ v6 if approved); owner checks and switches a2 on and pauses the Delhi ad set the same day; owner sets the account spending limit to amount spent + ₹3,000."}, {"when": "Week 1 (days 1-7)", "what": "No edits except the rule-1 exceptions. Call within 5 minutes from 10am to 7pm; night leads get a WhatsApp acknowledgement the same evening and a call by 10:30am. Grade day leads by 7pm and night leads by noon. Day-7 check: cost per 1,000 views and spend by state, reported only."}, {"when": "Week 2 (days 8-14)", "what": "Day-8 low-volume check. Judge only ads with ₹500+ spend (v1 is likely first). Review city, who is filling, Physics & Maths share, NIOS-route share and funding split. Day 14 is the first day a state exclusion can be proposed."}, {"when": "Week 3 (days 15-21)", "what": "Pause rule on ads past ₹500. Brief one replacement Reel for week-5 fatigue, ideally from the owner's real footage (students, aircraft, Dwarka office); if v6 was held, it is the first replacement."}, {"when": "Week 4 (days 22-30)", "what": "Month report: leads, cost per lead, CPL-qualified, NIOS-route leads, admissions, Delhi NCR against the rest of India, calls within 5 minutes, same-day grading, loan-answer split. The owner decides the next month's budget."}], "measurement": ["Speed to lead: call within 5 minutes from 10am to 7pm (CRM timestamp). All 4 test leads arrived between 7:40 pm and 2:19 am IST; the 3 called so far were first called 13.1-15.5 hours later (median 13.5 h) and 1 is not yet called (CONTEXT.last_test, 23 Nov). Calling within 5 minutes instead of 30 makes reaching a lead about 100 times more likely (MIT / InsideSales lead response study).", "Thank-you call button: count taps on 'Call now' (Meta form insights) and inbound calls to 93555 66991 within 10 minutes of a form, against leads.", "Same-day grading: day leads graded by 7pm, night leads by noon on the next calling morning. Track the share graded on time weekly.", "Loan readiness: counsellors use the owner's education-loan note on every first call (3 of 4 test leads chose 'Family + education loan'). Record whether a loan was discussed, with no approval promised.", "NIOS route track from day 1: every 'Passed with other subjects' lead is graded 'NIOS route'; it is a valid lead for the NIOS offer, never sent to Meta as Qualified and never closed as lost. Report NIOS-route leads and cost per NIOS-route lead weekly, by creative.", "Store the Meta lead ID, ad ID and form ID on every CRM lead, and log the first-call time and a grade for every lead.", "CRM stages to send to Meta daily (Conversions API for CRM): Lead → Contacted → Qualified (as in goal.kpi) → Counselling (visit or online) → Admission. NIOS route is not sent as Qualified.", "Weekly: cost per 1,000 views; cost per lead per creative (late creatives counted from their go-live day); spend and leads by state; the form's city answer; who is filling (parents counted by form answer, lesson 9); the Physics & Maths share; NIOS-route share; funding split; cost per qualified lead.", "QUALITY_LEAD switch only when Meta leads reach about 200 a month (4 in the last 30 days). That needs about ₹8,000-12,000 a month at ₹40-60 per lead.", "No Meta Pixel on the account, so website audiences are not ready. Install it before any website retargeting."], "risks": ["The target of 500 is out of reach. ₹3,000 gives about 36-75 leads (likely 50), and many will be on the NIOS route, not CPL-qualified.", "₹100 a day keeps the ad set learning limited all month; results swing day to day, and with 4 ads Meta may give 1-2 of them almost no spend.", "All-India view cost (₹78 per 1,000) is an estimate from regional history; country-wide lead ads have no history here, so the low case assumes no gain.", "No live ad states a fee figure until the owner settles the fee line, a gap against the CRM's premium rule; 'lakhs' is used without a number. If the owner rejects even that word, the CRM validator needs a change before the plan can pass.", "The thank-you call button needs a builder patch; Meta lead forms cannot be edited once published, so the button choice (call or WhatsApp) must be made before f2 is built.", "A call button after 7pm reaches an unanswered phone; most test leads came 7pm-2am. A WhatsApp button would suit night leads better but needs WhatsApp Business linked to the Page and a confirmed number (the website lists 93556 11996 for WhatsApp).", "The CRM refuses to build a new version once v3 is in Meta ('already created in Meta'); without the builder patch, a2, f2 and the new ads must be created by hand in Ads Manager.", "v1's live caption says 'Class 2 / Class 1 medical' and 'Call/WhatsApp: 93555 66991'; the owner kept v1 unchanged, but the medical classes are not on our website and WhatsApp on that number is unconfirmed.", "The Reels are Hinglish and name Dwarka; leads from the south and east may convert less. Students outside Delhi can take ground classes online, but flying is at partner flying schools; counsellors must say so plainly.", "NIOS-route leads need an owner-confirmed offer; until then counsellors give guidance only, and the track may not convert this month.", "Meta can overspend on single days (up to 7 × ₹100 a week); the account spending limit caps the total.", "DGCA approval and '16+ years' are unverified, so they stay out of all ads."], "patterns_used": ["Lead generation at ₹41 per lead (655 leads) → OUTCOME_LEADS with an Instant Form", "Conversations at ₹1,979 per lead and WhatsApp at ₹927 → no conversations or WhatsApp objective", "The country-wide IN loss came from conversations ad sets → not a reason against country-wide lead ads (lesson 11)", "'Pilot Training Nov (With Audiences)' at ₹39 per lead, 18-65, Advantage on → 18-65 with Advantage+ audience", "Feb 2026 north-India lead campaign at ₹46 per lead and ₹78 per 1,000 views → likely case and wide reach", "Test 20-23 Nov: v1 ₹72 per lead (top), v2 ₹116, views ₹168-206 per 1,000 in the Delhi radius → keep v1, go wide (lesson 3)", "Instagram Reels gave 117 of 191 leads → vertical Reels plus Advantage+ placements", "Short text ₹41 against long text ₹122 → short captions", "Fatigue curve (week 5 at 0.88, week 6 at 0.278) → refresh by day 21", "Lessons of 23 Nov: all India, fee consistency (v2 retired, no fee figures), ₹500 judging threshold, night leads, non-PCM next step (NIOS route), same-day grading, loan note, parents counted per form answer, close decisions before widening, gate launch on creative approval, carry rules word for word"], "sources": [{"title": "We One Aviation DGCA ground classes (online batches, 5 subjects, RTR(A), partner flying schools)", "url": "https://weoneaviation.in/dgca-ground-classes"}, {"title": "We One Aviation home (eligibility: 10+2 with Physics and Maths; DGCA medical; 200 hours; 12-18 months)", "url": "https://weoneaviation.in"}, {"title": "We One Aviation contact (C-404, Ramphal Chowk, Dwarka)", "url": "https://weoneaviation.in/contact"}, {"title": "We One Aviation privacy policy", "url": "https://weoneaviation.in/privacy-policy"}, {"title": "Air India cadet pilot eligibility (Physics and Maths at 10+2 can be taken through NIOS)", "url": "https://cadetpilot.airindia.com/in/en/eligibility-criteria.html"}, {"title": "Meta Graph API: Page leadgen_forms (thank_you_page button_type CALL_BUSINESS, WHATSAPP, business_phone_number)", "url": "https://developers.facebook.com/docs/graph-api/reference/page/leadgen_forms/"}, {"title": "Meta developers: Conversions API for CRM Integration", "url": "https://developers.facebook.com/docs/marketing-api/conversions-api/conversion-leads-integration"}, {"title": "Zapier: Meta guide to better lead quality (third-party)", "url": "https://www.zapier.com/blog/meta-guide-to-better-lead-quality/"}, {"title": "PPC Land: ad sets under 50 weekly conversions (third-party)", "url": "https://ppc.land/meta-says-ad-sets-under-50-weekly-conversions-cost-28-more-per-purchase/"}]}$plan$::jsonb FROM public.ads_meta_strategy WHERE title = 'V5 real';
